"""Score every task in the bank and report one pass rate."""
import json


def load(path="evals/tasks.jsonl"):
    return [json.loads(line) for line in open(path)]


def run_bank(agent, path="evals/tasks.jsonl"):
    tasks = load(path)
    hits = 0
    for task in tasks:
        if agent(task["prompt"]) == task["expect"]:
            hits += 1
    # Every task counts the same. A task whose grader can never pass is
    # charged to the agent exactly like a task the agent simply failed.
    return {"pass_rate": hits / len(tasks), "n": len(tasks)}

