good.evals/run_bank.py:
"""Score only tasks a human attested are solvable, and report what was held out."""
import json


def load(path="evals/tasks.jsonl"):
    return [json.loads(line) for line in open(path)]


def run_bank(agent, path="evals/tasks.jsonl"):
    tasks = load(path)
    scored, held_out = [], []
    for task in tasks:
        v = task.get("validity") or {}
        if not v.get("human_verified") or not v.get("solvable"):
            # Filter invalid tasks out of the denominator instead of billing
            # them to the agent, and keep the reason so the bank is auditable.
            held_out.append({"id": task["id"], "reason": v.get("exclude_reason", "unverified")})
            continue
        scored.append(agent(task["prompt"]) == task["expect"])
    return {
        "pass_rate": sum(scored) / len(scored),
        "n_scored": len(scored),
        "held_out": held_out,
    }
